#include <vector>

class Solution {
public:
    int minFlips(std::vector<int>& bulbs) {
        int flips = 0;
        for (int b : bulbs) {
            if ((b + flips) % 2 == 0) flips++;
        }
        return flips;
    }
};

class Solution {
    public int minFlips(int[] bulbs) {
        int flips = 0;
        for (int b : bulbs) {
            if ((b + flips) % 2 == 0) flips++;
        }
        return flips;
    }
}

function minFlips(bulbs) {
